def tokenize(expr):
    tokens = []
    current_number = ''
    for char in expr:
        if char.isdigit() or char == '.':
            current_number += char
        else:
            if current_number:
                tokens.append(Token('NUMBER', float(current_number)))
                current_number = ''
            if char in "+-*/()":
                tokens.append(Token(char, char))
    if current_number:
        tokens.append(Token('NUMBER', float(current_number)))
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.current_token_index = 0

    def current_token(self):
        if self.current_token_index < len(self.tokens):
            return self.tokens[self.current_token_index]
        return None

    def eat(self, type_):
        if self.current_token() and self.current_token().type == type_:
            self.current_token_index += 1
            return True
        return False

    def factor(self):
        token = self.current_token()
        if token is not None:
            if self.eat('NUMBER'):
                return token.value
            if self.eat('('):
                result = self.expr()
                self.eat(')')
                return result
        raise SyntaxError("Invalid syntax")

    def term(self):
        result = self.factor()
        while self.current_token() and self.current_token().type in ('*', '/'):
            token = self.current_token()
            if self.eat('*'):
                result *= self.factor()
            elif self.eat('/'):
                result /= self.factor()
        return result

    def expr(self):
        result = self.term()
        while self.current_token() and self.current_token().type in ('+', '-'):
            token = self.current_token()
            if self.eat('+'):
                result += self.term()
            elif self.eat('-'):
                result -= self.term()
        return result

