    """Parses and evaluates an arithmetic expression respecting operator precedence."""
    tokens = tokenize(expr.replace(' ', ''))
    parser = Parser(tokens)
    return parser.expr()

class Evaluator:
    def __init__(self, expr):
        self.expr = expr
        self.pos = 0
        self.current_char = self.expr[self.pos]

    def error(self):
        raise Exception("Invalid character at position {}".format(self.pos))

    def advance(self):
        """Advance to the next character in the expression."""
        self.pos += 1
        if self.pos < len(self.expr):
            self.current_char = self.expr[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self):
        """Skip whitespace characters in the expression."""
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def parse_number(self):
        """Parse a number (integer or float) from the expression."""
        number_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            number_str += self.current_char
            self.advance()
        return float(number_str)

    def parse_factor(self):
        """Parse a factor, which can be a number or a parenthesis expression."""
        if self.current_char == '(':
            self.advance()
            result = self.parse_expression()
            if self.current_char == ')':
                self.advance()
                return result
            else:
                self.error()
        elif self.current_char.isdigit() or self.current_char == '.':
            return self.parse_number()
        else:
            self.error()

    def parse_term(self):
        """Parse a term, which includes factors and * or /."""
        result = self.parse_factor()
        while self.current_char in ('*', '/'):
            if self.current_char == '*':
                self.advance()
                result *= self.parse_factor()
            elif self.current_char == '/':
                self.advance()
                denominator = self.parse_factor()
                if denominator == 0:
                    raise ZeroDivisionError("Division by zero.")
                result /= denominator
        return result

    def parse_expression(self):
        """Parse an entire expression with + and -."""
        result = self.parse_term()
        while self.current_char in ('+', '-'):
            if self.current_char == '+':
                self.advance()
                result += self.parse_term()
            elif self.current_char == '-':
                self.advance()
                result -= self.parse_term()
        return result

def evaluate(expr: str) -> float:
    """Evaluates a mathematical expression using a recursive descent parser."""
    evaluator = Evaluator(expr)
    evaluator.skip_whitespace()
    return evaluator.parse_expression()

