        return result

    def parse_term(self):
        result = self.parse_factor()
        while self.index < len(self.expression):
            if self.expression[self.index] == '*':
                self.index += 1
                result *= self.parse_factor()
            elif self.expression[self.index] == '/':
                self.index += 1
                result /= self.parse_factor()
            else:
                break
        return result

    def parse_factor(self):
        if self.expression[self.index] == '(':
            self.index += 1
            result = self.parse_expression()
            self.index += 1  # Skip ')'
            return result
        else:
            return self.parse_number()

    def parse_number(self):
        start_index = self.index
        while (self.index < len(self.expression) and 
               (self.expression[self.index].isdigit() or self.expression[self.index] == '.')):
            self.index += 1
        return float(self.expression[start_index:self.index])

